#include "rpg_core.h"
#include <string.h>

static int valid_id(const char *s) { size_t i; if (!s || !s[0]) return 0; for(i=0;s[i];++i) if(i>=RPG_ITEM_ID_MAX) return 0; return 1; }
uint64_t rpg_experience_for_next_level(uint32_t level) { uint64_t n=level; if(!level || level>=RPG_MAX_LEVEL) return UINT64_MAX; return n*n*UINT64_C(1000); }
rpg_result rpg_grant_experience(rpg_character *c,uint64_t amount,uint32_t *gained) { uint32_t n=0; if(!c||!c->level||c->level>RPG_MAX_LEVEL) return RPG_ERR_ARGUMENT; if(UINT64_MAX-c->experience<amount) return RPG_ERR_OVERFLOW; c->experience+=amount; while(c->level<RPG_MAX_LEVEL) { uint64_t need=rpg_experience_for_next_level(c->level); if(need==UINT64_MAX||c->experience<need) break; c->experience-=need; ++c->level; ++n; } if(gained) *gained=n; return RPG_OK; }
rpg_result rpg_derive_stats(const rpg_character *c,rpg_derived_stats *o) { const rpg_attributes *a; if(!c||!o||!c->level||c->level>RPG_MAX_LEVEL) return RPG_ERR_ARGUMENT; a=&c->attributes; if(a->strength<0||a->agility<0||a->stamina<0||a->intellect<0||a->spirit<0) return RPG_ERR_ARGUMENT; o->max_health=100+(int64_t)a->stamina*10+(int64_t)c->level*20; o->max_mana=50+(int64_t)a->intellect*12+(int64_t)a->spirit*8; o->attack_power=(int64_t)a->strength*2+a->agility+c->level; o->armor=(int64_t)a->agility+a->stamina/2; return RPG_OK; }
rpg_result rpg_inventory_add(rpg_inventory *v,const char *id,uint32_t count,uint32_t max) { size_t i; uint32_t left=count; if(!v||!valid_id(id)||!count||!max||v->size>RPG_INVENTORY_CAPACITY) return RPG_ERR_ARGUMENT; for(i=0;i<v->size&&left;i++) { rpg_item_stack *s=&v->slots[i]; if(!strcmp(s->item_id,id)&&s->count<s->max_stack) { uint32_t room=s->max_stack-s->count,move=left<room?left:room; s->count+=move; left-=move; } } while(left) { rpg_item_stack *s; uint32_t move; if(v->size>=RPG_INVENTORY_CAPACITY) return RPG_ERR_CAPACITY; s=&v->slots[v->size]; move=left<max?left:max; strncpy(s->item_id,id,RPG_ITEM_ID_MAX); s->item_id[RPG_ITEM_ID_MAX]='\0'; s->count=move; s->max_stack=max; ++v->size; left-=move; } return RPG_OK; }
rpg_result rpg_inventory_remove(rpg_inventory *v,const char *id,uint32_t count) { size_t i; uint64_t have=0; uint32_t left=count; if(!v||!valid_id(id)||!count||v->size>RPG_INVENTORY_CAPACITY) return RPG_ERR_ARGUMENT; for(i=0;i<v->size;i++) if(!strcmp(v->slots[i].item_id,id)) have+=v->slots[i].count; if(have<count) return RPG_ERR_INSUFFICIENT; for(i=0;i<v->size&&left;i++) { rpg_item_stack *s=&v->slots[i]; if(strcmp(s->item_id,id)) continue; if(s->count>left) { s->count-=left; left=0; } else { left-=s->count; s->count=0; } } for(i=0;i<v->size;) { if(!v->slots[i].count) { size_t last=--v->size; if(i!=last) v->slots[i]=v->slots[last]; memset(&v->slots[last],0,sizeof(v->slots[last])); } else ++i; } return RPG_OK; }
rpg_result rpg_quest_add_progress(rpg_quest_progress *q,uint32_t index,uint32_t amount) { rpg_quest_objective *o; if(!q||q->turned_in>1||q->turned_in||q->objective_count>RPG_QUEST_OBJECTIVES||index>=q->objective_count) return RPG_ERR_ARGUMENT; o=&q->objectives[index]; if(UINT32_MAX-o->progress<amount) return RPG_ERR_OVERFLOW; o->progress+=amount; if(o->progress>o->required) o->progress=o->required; return RPG_OK; }
int rpg_quest_is_complete(const rpg_quest_progress *q) { uint32_t i; if(!q||!q->objective_count||q->objective_count>RPG_QUEST_OBJECTIVES) return 0; for(i=0;i<q->objective_count;i++) if(q->objectives[i].progress<q->objectives[i].required) return 0; return 1; }
